CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, display_name VARCHAR(120), status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE roles (id BIGINT PRIMARY KEY AUTO_INCREMENT, code VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL);
CREATE TABLE permissions (id BIGINT PRIMARY KEY AUTO_INCREMENT, code VARCHAR(100) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL);
CREATE TABLE user_roles (user_id BIGINT NOT NULL, role_id BIGINT NOT NULL, PRIMARY KEY(user_id, role_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE role_permissions (role_id BIGINT NOT NULL, permission_id BIGINT NOT NULL, PRIMARY KEY(role_id, permission_id), FOREIGN KEY(role_id) REFERENCES roles(id), FOREIGN KEY(permission_id) REFERENCES permissions(id));
CREATE TABLE production_batches (id BIGINT PRIMARY KEY AUTO_INCREMENT, batch_name VARCHAR(120) NOT NULL UNIQUE, status VARCHAR(30) NOT NULL DEFAULT 'DRAFT', created_by BIGINT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, committed_at TIMESTAMP NULL, FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE assets (id BIGINT PRIMARY KEY AUTO_INCREMENT, machine_sn VARCHAR(120) NOT NULL UNIQUE, contract_no VARCHAR(120), invoice_date DATE, model VARCHAR(120), batch_id BIGINT, factory_config_json JSON, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(batch_id) REFERENCES production_batches(id));
CREATE TABLE asset_components (id BIGINT PRIMARY KEY AUTO_INCREMENT, asset_id BIGINT NOT NULL, component_type VARCHAR(40) NOT NULL, model VARCHAR(160), serial_no VARCHAR(160) NOT NULL, metadata_json JSON, UNIQUE KEY uk_asset_component_sn(serial_no), FOREIGN KEY(asset_id) REFERENCES assets(id));
CREATE TABLE repair_orders (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_number VARCHAR(80) NOT NULL UNIQUE, asset_id BIGINT, machine_sn VARCHAR(120), customer_name VARCHAR(200) NOT NULL, discovery_phase VARCHAR(40), fault_description TEXT NOT NULL, actual_fault_description TEXT, status VARCHAR(30) NOT NULL, assigned_to BIGINT, shipment_config_json JSON, received_config_json JSON, report_data_json JSON, tracking_number VARCHAR(120), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, closed_at TIMESTAMP NULL, FOREIGN KEY(asset_id) REFERENCES assets(id), FOREIGN KEY(assigned_to) REFERENCES users(id));
CREATE TABLE repair_parts (id BIGINT PRIMARY KEY AUTO_INCREMENT, repair_order_id BIGINT NOT NULL, part_name VARCHAR(160) NOT NULL, old_sn VARCHAR(160), new_sn VARCHAR(160), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(repair_order_id) REFERENCES repair_orders(id));
CREATE TABLE lifecycle_events (id BIGINT PRIMARY KEY AUTO_INCREMENT, asset_id BIGINT NOT NULL, event_type VARCHAR(50) NOT NULL, part_name VARCHAR(160), old_sn VARCHAR(160), new_sn VARCHAR(160), details TEXT, operator_id BIGINT, occurred_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(asset_id) REFERENCES assets(id), FOREIGN KEY(operator_id) REFERENCES users(id));
CREATE TABLE order_status_history (id BIGINT PRIMARY KEY AUTO_INCREMENT, repair_order_id BIGINT NOT NULL, from_status VARCHAR(30), to_status VARCHAR(30) NOT NULL, reason VARCHAR(500), operator_id BIGINT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(repair_order_id) REFERENCES repair_orders(id), FOREIGN KEY(operator_id) REFERENCES users(id));
CREATE TABLE sales_initiations (id BIGINT PRIMARY KEY AUTO_INCREMENT, initiation_no VARCHAR(80) NOT NULL UNIQUE, customer_name VARCHAR(200) NOT NULL, project_name VARCHAR(200) NOT NULL, sales_owner BIGINT, quantity INT NOT NULL, requested_delivery_date DATE, delivery_location VARCHAR(255), priority VARCHAR(30), status VARCHAR(40) NOT NULL DEFAULT 'DRAFT', business_background TEXT, technical_summary TEXT, software_summary TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(sales_owner) REFERENCES users(id));
CREATE TABLE sales_server_requirements (id BIGINT PRIMARY KEY AUTO_INCREMENT, initiation_id BIGINT NOT NULL, server_model VARCHAR(160), quantity INT NOT NULL, cpu_requirement TEXT, memory_requirement TEXT, storage_requirement TEXT, network_requirement TEXT, custom_description TEXT, FOREIGN KEY(initiation_id) REFERENCES sales_initiations(id));
CREATE TABLE sales_software_requirements (id BIGINT PRIMARY KEY AUTO_INCREMENT, initiation_id BIGINT NOT NULL, os_name VARCHAR(160), os_version VARCHAR(80), middleware TEXT, database_requirement TEXT, license_requirement TEXT, security_requirement TEXT, FOREIGN KEY(initiation_id) REFERENCES sales_initiations(id));
CREATE TABLE procurement_projects (id BIGINT PRIMARY KEY AUTO_INCREMENT, project_no VARCHAR(80) NOT NULL UNIQUE, initiation_id BIGINT NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'PENDING', quotation_deadline DATE, selected_supplier VARCHAR(200), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(initiation_id) REFERENCES sales_initiations(id));
INSERT INTO roles(code,name) VALUES ('ADMIN','管理员'),('MANAGER','服务经理'),('TECHNICIAN','技术工程师'),('PRODUCTION','生产专员'),('SALES','销售'),('PROCUREMENT','采购');
INSERT INTO permissions(code,name) VALUES ('VIEW_DASHBOARD','查看仪表盘'),('VIEW_ORDERS','查看工单'),('MANAGE_ORDERS','管理工单'),('VIEW_PRODUCTION','查看生产'),('MANAGE_PRODUCTION','管理生产'),('MANAGE_SALES','管理销售立项'),('MANAGE_PROCUREMENT','管理采购');
